/**
 * A beleza das equações — a·x + b = c desenhada como o que ela é: uma balança.
 *
 * O sinal de igual é o fiel. Enquanto os dois lados não pesam o mesmo, o braço
 * pende, e o lado que desce é o lado pesado — é essa leitura, e não a conta, que
 * o módulo quer ensinar a uma criança. Por isso a cena não mostra "esq = 7,
 * dir = 11": ela mostra sete caixinhas contra onze, e o braço torto.
 *
 * As caixas de `x` são azuis e mudam de tamanho com o valor escolhido; as
 * unidades soltas são douradas e sempre do mesmo tamanho. Assim dá para VER que
 * mexer no x mexe em `a` caixas de uma vez.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  infoDe,
  limitar,
  MATERIAIS,
  numeroDe,
  paleta,
  retangulo,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

/** Inclinação máxima do braço, em radianos (~11°). */
const INCLINACAO = 0.19;

const balanca: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};
  // O braço persegue o alvo em vez de saltar: o pêndulo é metade da explicação.
  let inclinacaoAtual = 0;

  /** Uma pilha de pesos num prato, em fileiras que crescem para cima. */
  function pilha(
    ctx: CanvasRenderingContext2D,
    cx: number,
    base: number,
    largura: number,
    caixasX: number,
    valorX: number,
    unidades: number,
    tinta: string,
  ): void {
    const cor = paleta();
    const lado = limitar(largura / 5.5, 7, 17);
    const vao = lado * 0.28;

    // As caixas de x, lado a lado sobre o prato.
    const alturaCaixa = lado * limitar(0.6 + valorX * 0.18, 0.6, 2.6);
    const larguraTotal = caixasX * lado + Math.max(0, caixasX - 1) * vao;
    let x = cx - larguraTotal / 2;

    for (let i = 0; i < caixasX; i++) {
      retangulo(ctx, x, base - alturaCaixa, lado, alturaCaixa, 3, tinta, cor.texto, 1);
      texto(ctx, 'x', x + lado / 2, base - alturaCaixa / 2, lado * 0.62, {
        cor: cor.contraste,
        peso: 800,
      });
      x += lado + vao;
    }

    // As unidades, em fileiras de até cinco, ao lado das caixas.
    const porFila = 5;
    const ladoUnidade = lado * 0.62;
    const inicioY = base - ladoUnidade;
    const filas = Math.ceil(unidades / porFila);

    for (let i = 0; i < unidades; i++) {
      const fila = Math.floor(i / porFila);
      const coluna = i % porFila;
      const nesta = Math.min(porFila, unidades - fila * porFila);
      const larguraFila = nesta * ladoUnidade + Math.max(0, nesta - 1) * (ladoUnidade * 0.2);
      const ux = cx - larguraFila / 2 + coluna * ladoUnidade * 1.2;
      const uy = inicioY - fila * ladoUnidade * 1.2 - (caixasX > 0 ? alturaCaixa + 4 : 0);
      retangulo(ctx, ux, uy, ladoUnidade, ladoUnidade, 2, cor.ouro, cor.texto, 0.8);
    }

    // Quantas unidades — contar quinze cubinhos na tela não é o ponto.
    if (unidades > 0) {
      const topo =
        inicioY -
        (filas - 1) * ladoUnidade * 1.2 -
        (caixasX > 0 ? alturaCaixa + 4 : 0) -
        lado * 0.5;
      texto(ctx, `${unidades}`, cx, topo, limitar(lado * 0.7, 8, 12), {
        cor: cor.fraco,
        peso: 700,
      });
    }
  }

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number): void {
    const cor = paleta();
    const info = infoDe(estado);

    const a = Math.max(0, Math.trunc(numeroDe(info, 'a', 2)));
    const b = Math.trunc(numeroDe(info, 'b', 3));
    const c = Math.trunc(numeroDe(info, 'c', 11));
    const x = Math.trunc(numeroDe(info, 'x', 0));
    const esquerda = numeroDe(info, 'esq', a * x + b);
    const direita = numeroDe(info, 'dir', c);
    const ok = info.ok === true;

    titulo(ctx, L, A, `${a}x ${b < 0 ? '−' : '+'} ${Math.abs(b)} = ${c}`);

    // A diferença satura em ±6: além disso o braço já bateu no limite.
    const alvo = -limitar((esquerda - direita) / 6, -1, 1) * INCLINACAO;
    inclinacaoAtual += (alvo - inclinacaoAtual) * 0.12;
    const angulo = ok ? inclinacaoAtual * 0.4 : inclinacaoAtual;

    const cx = L / 2;
    const eixo = A * 0.44;
    const braco = L * 0.34;
    const tinta = ok ? cor.verde : cor.azul;

    // ── A coluna e a base ────────────────────────────────────────────────
    const chao = A * 0.86;
    retangulo(ctx, cx - L * 0.11, chao, L * 0.22, A * 0.035, 4, MATERIAIS.madeira);
    retangulo(ctx, cx - L * 0.014, eixo, L * 0.028, chao - eixo, 3, MATERIAIS.prata, cor.trilho, 1);

    // ── O braço ──────────────────────────────────────────────────────────
    const dx = Math.cos(angulo) * braco;
    const dy = Math.sin(angulo) * braco;

    ctx.strokeStyle = MATERIAIS.prata;
    ctx.lineWidth = Math.max(4, A * 0.018);
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(cx - dx, eixo - dy);
    ctx.lineTo(cx + dx, eixo + dy);
    ctx.stroke();

    // O fiel: o "=" da equação, verde quando os pratos nivelam.
    ctx.fillStyle = tinta;
    ctx.beginPath();
    ctx.moveTo(cx, eixo - A * 0.05);
    ctx.lineTo(cx - A * 0.028, eixo + A * 0.006);
    ctx.lineTo(cx + A * 0.028, eixo + A * 0.006);
    ctx.closePath();
    ctx.fill();

    // ── Os pratos ────────────────────────────────────────────────────────
    const larguraPrato = L * 0.26;

    const prato = (px: number, py: number, desenharPesos: () => void): void => {
      // As cordas.
      ctx.strokeStyle = MATERIAIS.corda;
      ctx.lineWidth = 1.4;
      for (const lado of [-1, 1]) {
        ctx.beginPath();
        ctx.moveTo(px, py);
        ctx.lineTo(px + (larguraPrato / 2) * lado, py + A * 0.13);
        ctx.stroke();
      }

      const base = py + A * 0.13;
      desenharPesos();
      retangulo(
        ctx,
        px - larguraPrato / 2,
        base,
        larguraPrato,
        A * 0.022,
        A * 0.011,
        MATERIAIS.prata,
        cor.trilho,
        1,
      );
    };

    prato(cx - dx, eixo - dy, () => {
      pilha(ctx, cx - dx, eixo - dy + A * 0.13, larguraPrato, a, x, Math.max(0, b), tinta);
    });
    prato(cx + dx, eixo + dy, () => {
      pilha(ctx, cx + dx, eixo + dy + A * 0.13, larguraPrato, 0, 0, Math.max(0, c), cor.ouro);
    });

    // ── A conta, escrita ─────────────────────────────────────────────────
    const miudo = limitar(A * 0.042, 10, 14);
    texto(
      ctx,
      `x = ${x}   →   ${a}·${x} ${b < 0 ? '−' : '+'} ${Math.abs(b)} = ${esquerda}`,
      L / 2,
      A * 0.19,
      miudo,
      { cor: tinta, peso: 700 },
    );

    rodape(
      ctx,
      L,
      A,
      ok,
      `Os dois lados pesam ${c}: x = ${x} ✔`,
      esquerda < direita
        ? 'O lado direito é mais pesado: aumente o x.'
        : 'O lado esquerdo é mais pesado: diminua o x.',
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A }) => desenhar(ctx, L, A),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default balanca;
